import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[] f = new int[n];
        for (int i = 0; i < n; i++) f[i] = fs.nextInt();

        List<Integer>[] g = new ArrayList[n];
        List<Integer>[] rg = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(b);
            rg[b].add(a);
        }

        // Kosaraju to find SCCs
        boolean[] vis = new boolean[n];
        int[] order = new int[n];
        int ordPtr = 0;

        for (int i = 0; i < n; i++) {
            if (!vis[i]) {
                Deque<Integer> stack = new ArrayDeque<>();
                Deque<Integer> iterStack = new ArrayDeque<>();
                stack.push(i);
                iterStack.push(0);
                vis[i] = true;
                while (!stack.isEmpty()) {
                    int v = stack.peek();
                    int it = iterStack.pop();
                    if (it < g[v].size()) {
                        int to = g[v].get(it);
                        iterStack.push(it + 1);
                        if (!vis[to]) {
                            vis[to] = true;
                            stack.push(to);
                            iterStack.push(0);
                        }
                    } else {
                        stack.pop();
                        order[ordPtr++] = v;
                    }
                }
            }
        }

        int[] comp = new int[n];
        Arrays.fill(comp, -1);
        int compCnt = 0;

        for (int i = ordPtr - 1; i >= 0; i--) {
            int v = order[i];
            if (comp[v] == -1) {
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(v);
                comp[v] = compCnt;
                while (!stack.isEmpty()) {
                    int u = stack.pop();
                    for (int to : rg[u]) {
                        if (comp[to] == -1) {
                            comp[to] = compCnt;
                            stack.push(to);
                        }
                    }
                }
                compCnt++;
            }
        }

        List<Integer>[] compNodes = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) compNodes[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) compNodes[comp[i]].add(i);

        // Build condensation graph
        List<Integer>[] cg = new ArrayList[compCnt];
        List<Integer>[] rcg = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) {
            cg[i] = new ArrayList<>();
            rcg[i] = new ArrayList<>();
        }

        boolean[] hasEdge = new boolean[compCnt];
        for (int v = 0; v < n; v++) {
            int cv = comp[v];
            for (int to : g[v]) {
                int cu = comp[to];
                if (cv != cu) {
                    cg[cv].add(cu);
                    rcg[cu].add(cv);
                }
            }
        }

        // Remove duplicate edges
        for (int i = 0; i < compCnt; i++) {
            List<Integer> list = cg[i];
            if (list.size() > 1) {
                Collections.sort(list);
                int sz = 0;
                int prev = -1;
                for (int x : list) {
                    if (x != prev) {
                        list.set(sz++, x);
                        prev = x;
                    }
                }
                while (list.size() > sz) list.remove(list.size() - 1);
            }
        }
        for (int i = 0; i < compCnt; i++) {
            List<Integer> list = rcg[i];
            if (list.size() > 1) {
                Collections.sort(list);
                int sz = 0;
                int prev = -1;
                for (int x : list) {
                    if (x != prev) {
                        list.set(sz++, x);
                        prev = x;
                    }
                }
                while (list.size() > sz) list.remove(list.size() - 1);
            }
        }

        boolean[] compHasAssign = new boolean[compCnt];
        boolean[] compHasUse = new boolean[compCnt];
        for (int c = 0; c < compCnt; c++) {
            for (int v : compNodes[c]) {
                if (f[v] == 1) compHasAssign[c] = true;
                if (f[v] == 2) compHasUse[c] = true;
            }
        }

        // DP from assign components forward
        boolean[] canReachUse = new boolean[compCnt];
        int[] indeg = new int[compCnt];
        for (int i = 0; i < compCnt; i++) {
            for (int to : cg[i]) indeg[to]++;
        }

        int[] topo = new int[compCnt];
        int tp = 0;
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < compCnt; i++) if (indeg[i] == 0) q.add(i);
        while (!q.isEmpty()) {
            int v = q.poll();
            topo[tp++] = v;
            for (int to : cg[v]) {
                if (--indeg[to] == 0) q.add(to);
            }
        }

        for (int i = 0; i < compCnt; i++) {
            if (compHasUse[i]) canReachUse[i] = true;
        }
        for (int i = compCnt - 1; i >= 0; i--) {
            int v = topo[i];
            for (int to : cg[v]) {
                if (canReachUse[to]) canReachUse[v] = true;
            }
        }

        // DP backward from use components
        boolean[] canReachAssign = new boolean[compCnt];
        int[] outdeg = new int[compCnt];
        for (int i = 0; i < compCnt; i++) {
            for (int to : cg[i]) outdeg[i]++;
        }

        int[] rtopo = new int[compCnt];
        int rtp = 0;
        q.clear();
        for (int i = 0; i < compCnt; i++) if (outdeg[i] == 0) q.add(i);
        while (!q.isEmpty()) {
            int v = q.poll();
            rtopo[rtp++] = v;
            for (int from : rcg[v]) {
                if (--outdeg[from] == 0) q.add(from);
            }
        }

        for (int i = 0; i < compCnt; i++) {
            if (compHasAssign[i]) canReachAssign[i] = true;
        }
        for (int i = compCnt - 1; i >= 0; i--) {
            int v = rtopo[i];
            for (int from : rcg[v]) {
                if (canReachAssign[from]) canReachAssign[v] = true;
            }
        }

        // Mark components that lie on some assign->use path
        boolean[] onPath = new boolean[compCnt];
        for (int i = 0; i < compCnt; i++) {
            if (canReachUse[i] && canReachAssign[i]) onPath[i] = true;
        }

        int[] ans = new int[n];
        for (int v = 0; v < n; v++) {
            if (onPath[comp[v]]) ans[v] = 1;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
}

