    static List<Integer>[] g, rg;
    static int[] comp;          // component id for each node
    static int compCnt;
    static boolean[] used;
    static List<Integer> order;
    static List<Integer>[] cg;  // condensed graph
    static int[] compType;      // 0: none, 1: assign-only, 2: use-only, 3: both
    static boolean[] hasAssignReachable;
    static boolean[] hasUseReachable;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String s = fs.next();
        if (s == null) return;
        n = Integer.parseInt(s);
