        Arrays.fill(comp, -1);
        compCnt = 0;
        for (int i = order.size() - 1; i >= 0; i--) {
            int v = order.get(i);
            if (comp[v] == -1) {
                dfs2(v, compCnt);
                compCnt++;
            }
        }

        // Build condensed graph
        cg = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) cg[i] = new ArrayList<>();

        boolean[] seenEdge = new boolean[compCnt * 2]; // simple dedup not perfect but ok
        for (int v = 0; v < n; v++) {
            int cv = comp[v];
            for (int to : g[v]) {
                int cu = comp[to];
                if (cv != cu) {
                    cg[cv].add(cu);
                }
            }
        }

        // Determine component types
        compType = new int[compCnt];
        for (int i = 0; i < n; i++) {
            int c = comp[i];
            if (f[i] == 1) compType[c] |= 1;
            else if (f[i] == 2) compType[c] |= 2;
        }

        // DP on condensed graph: forward for assign reachability
        hasAssignReachable = new boolean[compCnt];
        hasUseReachable = new boolean[compCnt];

        // Topological order of condensed graph (it's DAG)
        int[] indeg = new int[compCnt];
        for (int i = 0; i < compCnt; i++) {
            for (int to : cg[i]) indeg[to]++;
        }
        int[] topo = new int[compCnt];
