        for (int i = 0; i < compCnt; i++) {
            if ((compType[i] & 2) != 0) hasUseReachable[i] = true;
        }
        for (int i = compCnt - 1; i >= 0; i--) {
            int v = topo[i];
            if (hasUseReachable[v]) {
                for (int from : rcg[v]) {
                    if (!hasUseReachable[from]) hasUseReachable[from] = true;
                }
            }
        }

        // For each node, interesting if its component has both assign and use reachable
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int c = comp[i];
            int ans = (hasAssignReachable[c] && hasUseReachable[c]) ? 1 : 0;
            sb.append(ans).append('\n');
        }
