        int n = Integer.parseInt(first);
        int m = fs.nextInt();

        int[] f = new int[n];
        for (int i = 0; i < n; i++) f[i] = fs.nextInt();

        List<Integer>[] g = new ArrayList[n];
        List<Integer>[] rg = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(b);
            rg[b].add(a);
        }

        // Kosaraju to find SCCs
        boolean[] vis = new boolean[n];
        int[] order = new int[n];
        int ordPtr = 0;

        // iterative DFS for order
        for (int i = 0; i < n; i++) {
            if (!vis[i]) {
                Deque<Integer> stack = new ArrayDeque<>();
                Deque<Integer> itStack = new ArrayDeque<>();
                stack.push(i);
                itStack.push(0);
                vis[i] = true;
                while (!stack.isEmpty()) {
                    int v = stack.peek();
                    int idx = itStack.pop();
                    if (idx < g[v].size()) {
                        int to = g[v].get(idx);
                        itStack.push(idx + 1);
                        if (!vis[to]) {
                            vis[to] = true;
                            stack.push(to);
                            itStack.push(0);
                        }
                    } else {
                        stack.pop();
                        order[ordPtr++] = v;
                    }
                }
            }
        }

        int[] comp = new int[n];
        Arrays.fill(comp, -1);
        int compCnt = 0;

        // reverse graph DFS to assign components
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            if (comp[v] == -1) {
                Deque<Integer> stack = new ArrayDeque<>();
                stack.push(v);
                comp[v] = compCnt;
                while (!stack.isEmpty()) {
                    int x = stack.pop();
                    for (int to : rg[x]) {
                        if (comp[to] == -1) {
                            comp[to] = compCnt;
                            stack.push(to);
                        }
                    }
                }
                compCnt++;
            }
        }

        // Build condensation DAG
        List<Integer>[] dag = new ArrayList[compCnt];
        List<Integer>[] rdag = new ArrayList[compCnt];
        for (int i = 0; i < compCnt; i++) {
            dag[i] = new ArrayList<>();
            rdag[i] = new ArrayList<>();
        }

        boolean[] hasAssign = new boolean[compCnt];
        boolean[] hasUse = new boolean[compCnt];
        for (int i = 0; i < n; i++) {
            int c = comp[i];
            if (f[i] == 1) hasAssign[c] = true;
            if (f[i] == 2) hasUse[c] = true;
        }

        // edges between components
        for (int v = 0; v < n; v++) {
            int cv = comp[v];
            for (int to : g[v]) {
                int cu = comp[to];
                if (cv != cu) {
                    dag[cv].add(cu);
                    rdag[cu].add(cv);
                }
            }
        }

        // remove duplicate edges (optional but helps)
        for (int i = 0; i < compCnt; i++) {
            Collections.sort(dag[i]);
            Collections.sort(rdag[i]);
            dag[i] = uniqueList(dag[i]);
            rdag[i] = uniqueList(rdag[i]);
        }

        // reachable from some assignment (forward)
        boolean[] fromAssign = new boolean[compCnt];
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < compCnt; i++) {
            if (hasAssign[i]) {
                fromAssign[i] = true;
                q.add(i);
            }
        }
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int to : dag[v]) {
                if (!fromAssign[to]) {
                    fromAssign[to] = true;
                    q.add(to);
                }
            }
        }

        // can reach some use (reverse)
        boolean[] toUse = new boolean[compCnt];
        q.clear();
        for (int i = 0; i < compCnt; i++) {
            if (hasUse[i]) {
                toUse[i] = true;
                q.add(i);
            }
        }
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int to : rdag[v]) {
                if (!toUse[to]) {
                    toUse[to] = true;
                    q.add(to);
                }
            }
        }

        // mark components that have assignment on path to use without intermediate assignment
        boolean[] goodComp = new boolean[compCnt];
        for (int i = 0; i < compCnt; i++) {
            if (fromAssign[i] && toUse[i]) {
                goodComp[i] = true;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(goodComp[comp[i]] ? '1' : '0').append('\n');
        }
        System.out.print(sb.toString());
    }

    private static List<Integer> uniqueList(List<Integer> list) {
        if (list.isEmpty()) return list;
        List<Integer> res = new ArrayList<>();
        int prev = list.get(0);
        res.add(prev);
        for (int i = 1; i < list.size(); i++) {
            int v = list.get(i);
            if (v != prev) {
                res.add(v);
                prev = v;
            }
        }
        return res;
    }
}

